+  // Lift the scratch-page transports into `state` (dual of the resume
+  // staging): the V dump sweep bytes back into state.vreg[] -- so the drained
+  // state carries vsim's actual V values, not QEMU 1's stale snapshot -- and
+  // the drain sd/fsd block-store sweeps (x1..x30 / f0..f31) into the GPR/FPR
+  // slots. Gated on the SAME fits conditions StateDrain used to pick
+  // sweep-vs-abstract: when the V page is full it read the registers via
+  // Abstract Commands and populated the state directly, so lifting stale
+  // scratch would clobber correct values. x31 (the GPR sweep base) was
+  // captured via abstract read inside the drain, so only x1..x30 lift.
+  // Shared by the exit drain and the reset-baseline capture.
+  void lift_scratch_blocks(hybrid_state_v1& state)
+  {
+    const std::span<const uint8_t> ram{platform.main_memory.data.data(),
+                                       platform.main_memory.data.size()};
+    if ((state.flags & HYBRID_FLAG_V) != 0u)
+      hybrid::read_v_from_scratch(state, ram);
+    if (hybrid::gpr_scratch_fits(state.vlenb))
+      hybrid::read_gpr_from_scratch(state, ram, 30);
+    if ((state.flags & HYBRID_FLAG_FP) != 0u
+        && hybrid::fpr_scratch_fits(state.vlenb))
+      hybrid::read_fpr_from_scratch(state, ram);
+  }
+
 public:

   void restore_context(const std::string& dir)
