// LG3: cache-file helpers for the engine reset-state baseline -- the
// hybrid_state_v1 drained from a freshly reset, halted hart that the
// liveness gate (ResumeDriver::set_reset_baseline) compares restores
// against. Pure path/IO helpers; the capture itself lives in the simulator
// (it needs the DMI bus and the scratch-page lifts).

#pragma once

#include "hybrid/state_abi.h"
#include "hybrid/state_loader.hpp"

#include <cstdint>
#include <filesystem>
#include <fstream>
#include <optional>
#include <string>
#include <string_view>

namespace hybrid {

// <engine>-<version>-<binary mtime>-<binary size>-<elf mtime>-<elf size>.bin
// The binary identity invalidates the cache on rebuild. The ELF identity is
// part of the key because the hart free-runs a few workload instructions
// between reset and the DMI halt, so the halted state is deterministic
// per-(engine build, ELF), not per-engine.
inline auto reset_baseline_file_name(std::string_view engine,
                                     std::string_view version,
                                     uint64_t bin_mtime, uint64_t bin_size,
                                     uint64_t elf_mtime, uint64_t elf_size)
  -> std::string
{
  return std::string{engine} + "-" + std::string{version} + "-"
       + std::to_string(bin_mtime) + "-" + std::to_string(bin_size) + "-"
       + std::to_string(elf_mtime) + "-" + std::to_string(elf_size) + ".bin";
}

// $XDG_CACHE_HOME/andesim, else $HOME/.cache/andesim, else "" (disabled).
// Env values are injected so the resolution is unit-testable.
inline auto reset_baseline_cache_root(const char* xdg_cache_home,
                                      const char* home)
  -> std::filesystem::path
{
  if (xdg_cache_home && *xdg_cache_home)
    return std::filesystem::path{xdg_cache_home} / "andesim";
  if (home && *home)
    return std::filesystem::path{home} / ".cache" / "andesim";
  return {};
}

// nullopt on any load_state failure (missing / short / bad magic / wrong
// version) -- a stale or corrupt cache entry means "capture again", never
// an aborted run.
inline auto try_load_reset_baseline(const std::filesystem::path& p)
  -> std::optional<hybrid_state_v1>
{
  try {
    return load_state(p.string());
  } catch (const std::exception&) {
    return std::nullopt;
  }
}

// Create parent directories and write the raw struct. False on any failure
// -- the cache is an optimization, never a reason to abort a run.
inline auto save_reset_baseline(const std::filesystem::path& p,
                                const hybrid_state_v1& s) -> bool
{
  std::error_code ec;
  if (p.has_parent_path())
    std::filesystem::create_directories(p.parent_path(), ec);
  std::ofstream f(p, std::ios::binary | std::ios::trunc);
  if (!f) return false;
  f.write(reinterpret_cast<const char*>(&s), sizeof s);
  return static_cast<bool>(f);
}

}  // namespace hybrid

// LG3: cache-file helpers for the engine reset-state baseline (the
// hybrid_state_v1 the liveness gate compares restores against).

#include "hybrid/reset_baseline.hpp"

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include <doctest.h>

#include <cstring>
#include <filesystem>
#include <fstream>

namespace fs = std::filesystem;

namespace {

auto make_state() -> hybrid_state_v1
{
  hybrid_state_v1 s{};
  s.magic = HYBRID_STATE_MAGIC;
  s.version = HYBRID_STATE_VERSION;
  s.flags = HYBRID_FLAG_RV64 | HYBRID_FLAG_ANDES;
  s.andes.mxstatus = 0x1122;
  s.mepc = 0x33;
  s.vreg[100] = 0xAB;
  return s;
}

auto tmpdir() -> fs::path
{
  const auto d = fs::temp_directory_path() / "reset_baseline_test";
  fs::remove_all(d);
  fs::create_directories(d);
  return d;
}

}  // namespace

TEST_CASE("cache file name encodes engine, version, and the binary+elf "
          "identity (the pre-halt free-run makes the state per-ELF)")
{
  CHECK(hybrid::reset_baseline_file_name("sim_x", "abc1", 12, 34, 56, 78)
        == "sim_x-abc1-12-34-56-78.bin");
}

TEST_CASE("cache root: XDG_CACHE_HOME wins, HOME/.cache is the fallback, "
          "neither -> empty (cache disabled)")
{
  CHECK(hybrid::reset_baseline_cache_root("/xdg", "/home/u")
        == fs::path("/xdg/andesim"));
  CHECK(hybrid::reset_baseline_cache_root(nullptr, "/home/u")
        == fs::path("/home/u/.cache/andesim"));
  CHECK(hybrid::reset_baseline_cache_root("", "/home/u")
        == fs::path("/home/u/.cache/andesim"));
  CHECK(hybrid::reset_baseline_cache_root(nullptr, nullptr).empty());
}

TEST_CASE("save + load round-trip preserves the state bytes, creating "
          "parent directories")
{
  const auto f = tmpdir() / "a" / "b" / "base.bin";
  const auto s = make_state();
  REQUIRE(hybrid::save_reset_baseline(f, s));
  const auto back = hybrid::try_load_reset_baseline(f);
  REQUIRE(back.has_value());
  CHECK(std::memcmp(&*back, &s, sizeof s) == 0);
}

TEST_CASE("missing, truncated, or bad-magic files load as nullopt")
{
  const auto d = tmpdir();
  CHECK_FALSE(hybrid::try_load_reset_baseline(d / "absent.bin").has_value());

  const auto short_f = d / "short.bin";
  {
    std::ofstream out(short_f, std::ios::binary);
    out << "xyz";
  }
  CHECK_FALSE(hybrid::try_load_reset_baseline(short_f).has_value());

  auto bad = make_state();
  bad.magic = 0x1234;
  const auto bad_f = d / "bad.bin";
  REQUIRE(hybrid::save_reset_baseline(bad_f, bad));
  CHECK_FALSE(hybrid::try_load_reset_baseline(bad_f).has_value());
}

